private static string FormatDateFromColumns(DataRow drw, params string[] columnNames)
{
    if (columnNames == null)
        return "";

    for (int i = 0; i < columnNames.Length; i++)
    {
        string strFormatted = FormatDateValue(drw, columnNames[i]);
        if (!string.IsNullOrEmpty(strFormatted))
            return strFormatted;
    }
    return "";
}

private static string GetDayOfCourseText(DataRow drw)
{
    string strDay = GetString(drw, "DayOfCourse");
    if (!string.IsNullOrEmpty(strDay))
        return strDay;

    DateTime? dtmStart = GetDateTimeFromColumns(drw, "StartAt", "ContractSignDate");
    DateTime? dtmFinish = GetDateTimeFromColumn(drw, "FinishAt");
    if (!dtmStart.HasValue || !dtmFinish.HasValue)
        return "";

    if (dtmFinish.Value < dtmStart.Value)
        return "";

    int intDays = (dtmFinish.Value.Date - dtmStart.Value.Date).Days + 1;
    return intDays.ToString();
}

